var matn = $json.matn || '';
var variant = $json.variant || 'full';
var faktlar = $json.faktlar || [];

// 1. Turkish normalization
function normTR(s) {
  return String(s || '').toLowerCase()
    .replace(/İ/g, 'i').replace(/I/g, 'ı')
    .replace(/ı/g, 'i')
    .replace(/ğ/g, 'g').replace(/ş/g, 's').replace(/ç/g, 'c')
    .replace(/ö/g, 'o').replace(/ü/g, 'u');
}

var matnN = normTR(matn);
var topilmalar = [];

// 2. RED list (normalized)
var RED_RAW = [
  'garanti eder','garanti ediyoruz','garantili',
  'kesin kar','kesin kazanc','risksiz',
  'zahmetsiz gelir','gunde kazan','ayda kazan',
  'hizli zengin','mutlaka kazanirsin','kesinlikle kazanir',
  'yatirim tavsiyesi'
];
// Normalize RED list
var RED = RED_RAW.map(normTR);

// ORANGE list (metasafe only)
var ORANGE_RAW = [
  'challenge','prop firma','funded','payout',
  'kaldirac','spread','hesap ac','fiyat tablosu',
  'a-book','instant pro','prime'
];
var ORANGE = ORANGE_RAW.map(normTR);

// Exception phrases (normalized)
var EXCEPTIONS_RAW = ['garanti degil','garanti vermiyoruz','garanti yoktur'];
var EXCEPTIONS = EXCEPTIONS_RAW.map(normTR);

// 3. Check RED list with LOCAL exception (±25 chars)
for (var ri = 0; ri < RED.length; ri++) {
  var redPhrase = RED[ri];
  var idx = matnN.indexOf(redPhrase);
  while (idx >= 0) {
    // Check local exception within ±25 chars
    var start = Math.max(0, idx - 25);
    var end = Math.min(matnN.length, idx + redPhrase.length + 25);
    var localCtx = matnN.slice(start, end);
    var isExcepted = false;
    for (var ei = 0; ei < EXCEPTIONS.length; ei++) {
      if (localCtx.indexOf(EXCEPTIONS[ei]) >= 0) {
        isExcepted = true;
        break;
      }
    }
    if (!isExcepted) {
      topilmalar.push({
        tur: 'RED',
        atama: RED_RAW[ri],
        parcha: matn.slice(Math.max(0, idx - 20), idx + redPhrase.length + 20)
      });
    }
    idx = matnN.indexOf(redPhrase, idx + 1);
  }
}

// 4. Check ORANGE list (metasafe only)
if (variant === 'metasafe') {
  for (var oi = 0; oi < ORANGE.length; oi++) {
    var orangePhrase = ORANGE[oi];
    var oidx = matnN.indexOf(orangePhrase);
    if (oidx >= 0) {
      topilmalar.push({
        tur: 'ORANGE',
        atama: ORANGE_RAW[oi],
        parcha: matn.slice(Math.max(0, oidx - 20), oidx + orangePhrase.length + 20)
      });
    }
  }
}

// 5. Number check: every % number in text must be in faktlar
// Parse numbers from faktlar
var faktlarRaqamlar = [];
for (var fi = 0; fi < faktlar.length; fi++) {
  var fm = String(faktlar[fi].matn || '');
  // Extract all numbers from faktlar text
  var fmatches = fm.match(/[0-9]+(?:[.,][0-9]+)?/g) || [];
  for (var fmi = 0; fmi < fmatches.length; fmi++) {
    faktlarRaqamlar.push(parseFloat(fmatches[fmi].replace(',', '.')));
  }
  // Also check qiymat field
  if (faktlar[fi].qiymat) {
    var qVal = String(faktlar[fi].qiymat || '');
    var qMatch = qVal.match(/[0-9]+(?:[.,][0-9]+)?/g) || [];
    for (var qi = 0; qi < qMatch.length; qi++) faktlarRaqamlar.push(parseFloat(qMatch[qi].replace(',', '.')));
  }
}

// Turkish number words to digits
var trNums = {
  'sifir':0,'bir':1,'iki':2,'uc':3,'dort':4,'bes':5,
  'alti':6,'yedi':7,'sekiz':8,'dokuz':9,'on':10,
  'yirmi':20,'otuz':30,'kirk':40,'elli':50,
  'altmis':60,'yetmis':70,'seksen':80,'doksan':90,
  'yuz':100,'bin':1000
};

// Find % numbers in matn
// Match patterns: %97, %74-89, yüzde doksan yedi etc
var percentPattern = new RegExp('%([0-9]+(?:[,.-][0-9]+)?)', 'g');
var pm;
while ((pm = percentPattern.exec(matn)) !== null) {
  var numStr = pm[1].replace(',', '.');
  var numVal = parseFloat(numStr);
  // Check if this number (or range component) is in faktlar
  var found = false;
  for (var fk = 0; fk < faktlarRaqamlar.length; fk++) {
    if (Math.abs(faktlarRaqamlar[fk] - numVal) < 0.5) { found = true; break; }
  }
  if (!found && faktlar.length > 0) {
    topilmalar.push({
      tur: 'IXTIRO_RAQAM',
      atama: pm[0],
      parcha: matn.slice(Math.max(0, pm.index - 15), pm.index + pm[0].length + 15)
    });
  }
}

var holat = topilmalar.length === 0 ? 'PASS' : 'FAIL';
return { json: { holat: holat, topilmalar: topilmalar, matn: matn, variant: variant, kutilgan: $json.kutilgan || null } };

